SELECT 
FROM wms_inventory
WHERE location_id = #{locationId}
  AND sku_id      = #{skuId}
  AND batch_no    IS NOT DISTINCT FROM #{batchNo,jdbcType=VARCHAR}
  AND serial_no   IS NOT DISTINCT FROM #{serialNo,jdbcType=VARCHAR}
  AND deleted = 0
FOR UPDATE
